//#region src/server/edge-api-runtime.d.ts
declare function isEdgeApiRuntime(runtime: string | undefined): boolean;
type EdgeApiExecutionRuntime = "node" | "worker";
/**
 * Remove wire-level body headers after Node's fetch implementation has decoded
 * an Edge API response. Next.js applies the same boundary in its edge sandbox.
 *
 * Workers keep the original response untouched: workerd preserves the encoded
 * body/header pair and can stream it directly to the client.
 */
declare function finalizeEdgeApiResponse(response: Response, runtime: EdgeApiExecutionRuntime): Response;
//#endregion
export { EdgeApiExecutionRuntime, finalizeEdgeApiResponse, isEdgeApiRuntime };